params.css:
#sheet{padding:18mm 6mm;}
#sheet > *{margin-left:38mm;margin-right:38mm;text-align:center;}
#sheet .inner > *{margin-left:38mm;margin-right:38mm;text-align:center;}
#sheet main > *{margin-left:38mm;margin-right:38mm;text-align:center;}
#sheet .frame > *{margin-left:38mm;margin-right:38mm;text-align:center;}
#sheet .card > *{margin-left:38mm;margin-right:38mm;text-align:center;}
#sheet > table.items{margin-left:0;margin-right:0;width:100%;text-align:left;}
#sheet .inner > table.items{margin-left:0;margin-right:0;width:100%;text-align:left;}
#sheet main > table.items{margin-left:0;margin-right:0;width:100%;text-align:left;}
#sheet .frame > table.items{margin-left:0;margin-right:0;width:100%;text-align:left;}
#sheet .card > table.items{margin-left:0;margin-right:0;width:100%;text-align:left;}
#sheet > *:last-child{margin-left:0;margin-right:0;}
#sheet .inner > *:last-child{margin-left:0;margin-right:0;}
#sheet main > *:last-child{margin-left:0;margin-right:0;}
#sheet .frame > *:last-child{margin-left:0;margin-right:0;}
#sheet .card > *:last-child{margin-left:0;margin-right:0;}
#sheet .f, #sheet .fld{text-align:left;}
#sheet .inner .f, #sheet .fld{text-align:left;}
#sheet main .f, #sheet .fld{text-align:left;}
#sheet .frame .f, #sheet .fld{text-align:left;}
#sheet .card .f, #sheet .fld{text-align:left;}
#sheet .frame{border:.3mm solid #555;padding:4mm;}
#sheet .inner .frame{border:.3mm solid #555;padding:4mm;}
#sheet main .frame{border:.3mm solid #555;padding:4mm;}
#sheet .frame .frame{border:.3mm solid #555;padding:4mm;}
#sheet .card .frame{border:.3mm solid #555;padding:4mm;}
#sheet{font-family:'LiberationSerif','DejaVu Serif',serif;line-height:1.42;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
